<?php
if(!defined('ABSPATH'))exit;
class Terttus_Product_Slider_Widget extends \Elementor\Widget_Base{
 public function get_name(){return 'terttus_product_slider';} public function get_title(){return 'Terttus Produkt Slider';} public function get_icon(){return 'eicon-slider-push';} public function get_categories(){return ['terttus-widgets'];}
 protected function register_controls(){$this->start_controls_section('q',['label'=>'Produkter']);$this->add_control('source',['label'=>'Vis','type'=>\Elementor\Controls_Manager::SELECT,'default'=>'latest','options'=>['latest'=>'Nyeste','featured'=>'Udvalgte','sale'=>'Tilbud']]);$this->add_control('limit',['label'=>'Antal','type'=>\Elementor\Controls_Manager::NUMBER,'default'=>10,'min'=>1,'max'=>30]);$this->end_controls_section();}
 protected function render(){if(!class_exists('WooCommerce'))return;$s=$this->get_settings_for_display();$a=['status'=>'publish','limit'=>(int)$s['limit'],'orderby'=>'date','order'=>'DESC'];if($s['source']==='featured')$a['featured']=true;if($s['source']==='sale')$a['include']=wc_get_product_ids_on_sale();$ps=wc_get_products($a);?><div class="tt-slider"><?php foreach($ps as $p):?><article class="tt-slide"><a href="<?php echo esc_url($p->get_permalink());?>"><?php echo $p->get_image('woocommerce_thumbnail');?><strong><?php echo esc_html($p->get_name());?></strong></a><div><?php echo wp_kses_post($p->get_price_html());?></div><a class="tt-add" href="<?php echo esc_url($p->add_to_cart_url());?>">Læg i kurv</a></article><?php endforeach;?></div><style>.tt-slider{display:flex;gap:18px;overflow-x:auto;scroll-snap-type:x mandatory;padding:2px 2px 14px}.tt-slide{scroll-snap-align:start;flex:0 0 250px;border:1px solid #e0e6ea;border-radius:14px;background:#fff;padding:16px}.tt-slide img{width:100%;aspect-ratio:1;object-fit:contain}.tt-slide strong{display:block;color:#10212d;margin:10px 0}.tt-slide a{text-decoration:none}.tt-add{display:block;margin-top:12px;background:#ff7b32;color:#fff!important;text-align:center;padding:10px;border-radius:8px;font-weight:700}</style><?php }
}\Elementor\Plugin::instance()->widgets_manager->register(new Terttus_Product_Slider_Widget());